class.description:
Pairs a local [member predict] effect with a reliable server request. The server receives a [NetwActionContext], validates at [member NetwActionContext.view_tick], and either binds an authoritative spawned [NetwEntity] result with [method NetwActionContext.bind] or denies it with [method NetwActionContext.deny].
Each authority method on an entity has its own slot, so actions created at one view tick use distinct effect keys. Create one with [method Netw.action]. The authority method must be a plain [Callable], not an RPC.
[codeblock]
@onready var place_bomb := Netw.action(_place_bomb)

func _ready() -> void:
    place_bomb.predict = _predict_bomb

func _network_tick(delta, tick, is_fresh) -> void:
    if is_fresh and inputs.bombing:
        place_bomb.request(tick)

func _place_bomb(ctx: NetwActionContext) -> void:
    var bomb := BOMB.instantiate()
    ctx.bind(bomb)
    $Bombs.add_child(bomb)
[/codeblock]
